  Directory.CreateDirectory(records);Directory.CreateDirectory(files);File.Copy(item.SourcePath,Path.Combine(files,md5+".cwp"));string record=Path.Combine(records,"28987_fixture.dat");byte[] bytes=Encoding.UTF8.GetBytes("0000"+Common.Json.Serialize(new{wpId="28987",wpName=md5+".cwp",wpMd5=md5,wpType=2}));for(int i=0;i<bytes.Length;i++)bytes[i]^=0xe7;File.WriteAllBytes(record,bytes);File.WriteAllText(Path.Combine(Common.Root,"tests","import-root.txt"),fixture);
