  var repeat=LocalImport.ReadRecord(record);Require(CandidateChecks.Load(repeat,()=>{})&&repeat.Check.CacheHit&&repeat.Check.HashedBytes==0&&repeat.Check.CoverKind==PreviewCovers.Kind,"Candidate cache lost screenshot or rehashed source");
  string renamed=Path.Combine(Common.Root,"tests","renamed-wallpaper.cwp");File.Copy(item.SourcePath,renamed);var alias=new WallpaperItem{Id="different-id",Name="different display name",SourcePath=renamed,RegisteredSha256=hash};string aliasHash=await Task.Run(()=>LocalImport.HashCancelable(renamed,()=>{}));PreviewCovers.NoteIdentity(renamed,aliasHash,CoverCache.Signature(renamed));using(var cover=WallpaperLibrary.LoadCover(alias))Require(cover!=null,"Same content renamed did not match");
