  try{Common.Root=moved;PreviewCovers.TestForgetIdentities();var restarted=new WallpaperLibrary();var restored=restarted.Doc.Items.Single(x=>x.Id==item.Id);restarted.DisplayHash(restored);var found=PreviewCovers.ForItem(restored);Require(found!=null&&PreviewCovers.ImagePath(found)==movedImage,"Restart/migration cover lookup failed");using(var cover=WallpaperLibrary.LoadCover(restored))Require(cover!=null,"Restart lost actual picture");}finally{Common.Root=root;library.DisplayHash(item);}
