  captureOperation=new ImportOperation(Write);captureTask=TestCancelledCapture(captureOperation,target);Close();await captureTask;for(int i=0;i<30&&!IsDisposed;i++)await Task.Delay(50);Require(IsDisposed&&!captureOperation.Busy,"Closing did not end pending capture");
